import os
import hashlib
import hmac
from pathlib import Path
from flask import Flask, request, jsonify, abort
import unicodedata

app = Flask(__name__)

BASE_DIR = os.environ.get('STORAGE_ROOT', '/var/data/documents')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key-change-in-prod')
ALLOWED_EXTENSIONS = {'.txt', '.md', '.json', '.xml', '.csv'}


def verify_token(token):
    """Verify HMAC-based authentication token."""
    if not token:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    timestamp, signature = parts
    expected = hmac.new(SECRET_KEY.encode(), timestamp.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)


def sanitize_filename(filename):
    """Remove potentially dangerous characters from filename."""
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Reject obvious traversal attempts
    if '..' in filename or filename.startswith('/'):
        return None
    # Only allow safe characters
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._- ')
    # Check each character is in allowed set
    for ch in filename:
        if ch not in allowed:
            return None
    return filename


def resolve_document_path(workspace, filename):
    """Resolve the full path for a document within a workspace."""
    # Validate workspace name (alphanumeric only)
    if not workspace.isalnum():
        return None
    # Sanitize the filename
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        return None
    # Apply NFC normalization for consistent storage
    normalized_name = unicodedata.normalize('NFC', clean_name)
    # Build the path
    full_path = os.path.join(BASE_DIR, workspace, normalized_name)
    return full_path


def check_extension(filepath):
    """Verify file has an allowed extension."""
    _, ext = os.path.splitext(filepath)
    return ext.lower() in ALLOWED_EXTENSIONS


@app.route('/api/v2/documents/<workspace>/<path:filename>', methods=['GET'])
def read_document(workspace, filename):
    token = request.headers.get('X-Auth-Token')
    if not verify_token(token):
        abort(401)

    filepath = resolve_document_path(workspace, filename)
    if filepath is None:
        abort(400, 'Invalid path')

    if not check_extension(filepath):
        abort(403, 'File type not allowed')

    try:
        with open(filepath, 'r') as f:
            content = f.read()
        return jsonify({'content': content, 'path': filename})
    except FileNotFoundError:
        abort(404)
    except Exception:
        abort(500)


@app.route('/api/v2/documents/<workspace>/<path:filename>', methods=['PUT'])
def write_document(workspace, filename):
    token = request.headers.get('X-Auth-Token')
    if not verify_token(token):
        abort(401)

    filepath = resolve_document_path(workspace, filename)
    if filepath is None:
        abort(400, 'Invalid path')

    if not check_extension(filepath):
        abort(403, 'File type not allowed')

    content = request.get_data(as_text=True)
    if len(content) > 1048576:  # 1MB limit
        abort(413)

    os.makedirs(os.path.dirname(filepath), exist_ok=True)
    with open(filepath, 'w') as f:
        f.write(content)

    return jsonify({'status': 'written', 'path': filename})


@app.route('/api/v2/documents/<workspace>', methods=['GET'])
def list_documents(workspace):
    token = request.headers.get('X-Auth-Token')
    if not verify_token(token):
        abort(401)

    if not workspace.isalnum():
        abort(400)

    workspace_dir = os.path.join(BASE_DIR, workspace)
    if not os.path.isdir(workspace_dir):
        return jsonify({'files': []})

    files = []
    for entry in os.scandir(workspace_dir):
        if entry.is_file() and check_extension(entry.name):
            files.append(entry.name)

    return jsonify({'files': sorted(files)})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
